def main():
    html = SRC.read_text(encoding="utf-8")
    missing = [en for en, _ in PAIRS if en not in html]
    if missing:
        print("Not found in index.html (update tools/build_tr.py):", file=sys.stderr)
        for en in missing:
            print("  - " + en[:110], file=sys.stderr)
        sys.exit(1)
    for en, tr in PAIRS:
        html = html.replace(en, tr)
    OUT.parent.mkdir(exist_ok=True)
    OUT.write_text(html, encoding="utf-8", newline="\n")
    print(f"Wrote {OUT.relative_to(ROOT)} ({len(PAIRS)} replacements)")


if __name__ == "__main__":
    main()
